function colName(index) {
  let n = index + 1;
  let name = "";
  while (n > 0) {
    const rem = (n - 1) % 26;
    name = String.fromCharCode(65 + rem) + name;
    n = Math.floor((n - 1) / 26);
  }
  return name;
}

const defaultColumnWidths = {
  Summary: [26, 120],
  Stories: [12, 28, 62, 72, 64, 58, 18, 72],
  Issues: [12, 12, 12, 22, 64, 74, 74, 74, 16],
  "Test Log": [12, 16, 22, 54, 84, 18],
  "Code Map": [34, 64, 92],
};

function writeTable(sheet, headers, rows, options = {}) {
  const values = [headers, ...rows];
  const lastCol = colName(headers.length - 1);
  const range = sheet.getRange(`A1:${lastCol}${values.length}`);
  range.values = values;
  sheet.showGridLines = false;
  sheet.freezePanes.freezeRows(1);
  range.format = {
    font: { name: "Aptos", size: 10, color: "#111827" },
    wrapText: true,
    borders: { preset: "inside", style: "thin", color: "#E5E7EB" },
  };
  sheet.getRange(`A1:${lastCol}1`).format = {
    fill: "#0F172A",
    font: { bold: true, color: "#FFFFFF", name: "Aptos", size: 10 },
  };
  sheet.getRange(`A1:${lastCol}1`).format.rowHeight = 28;
  if (values.length > 1) {
    sheet.getRange(`A2:${lastCol}${values.length}`).format.rowHeight = options.rowHeight ?? 48;
  }
  const widths = options.widths ?? defaultColumnWidths[sheet.name] ?? [];
  widths.forEach((width, index) => {
    const col = colName(index);
    sheet.getRange(`${col}1:${col}${values.length}`).format.columnWidth = width;
  });
}

